// Synchronous ROM initialised from a hex file ($readmemh). Infers block/distributed ROM.
// The .mem files are generated by scripts/hardware/hw_golden.py --write-mem.
module rom_sync #(
    parameter W    = 36,
    parameter AW   = 8,
    parameter FILE = "coef.mem"
) (
    input  wire          clk,
    input  wire [AW-1:0] addr,
    output reg  [W-1:0]  data
);
    reg [W-1:0] mem [0:(1<<AW)-1];

    initial $readmemh(FILE, mem);

    always @(posedge clk)
        data <= mem[addr];
endmodule
